  end if;
end $outer_0002$;

-- ▸ 0003_performance_payroll.sql
do $outer_0003$ begin
  if to_regclass('public.performance_policies') is not null then raise notice 'skip 0003_performance_payroll.sql (already applied)'; else
    raise notice 'apply 0003_performance_payroll.sql';
